INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00040000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 40), 'unit40-lesson1', 'Much, Many, A Lot (of): Quantity expressions', 'Use ''much'' in negative sentences and questions with uncountable nouns. Use ''many'' in negative sentences and questions with plural countable nouns. Use ''a lot of'' with both countable and uncountable nouns. Use ''a lot'' (without ''of'') when no noun follows.', $${"details":[{"concept":"Much – uncountable nouns","explanation":"We often use 'much' in negative sentences and questions, with uncountable nouns.","example":"I haven't got much lemonade. Have you got much water?","burmese":"'much' ကို uncountable nouns တွေနဲ့ negative sentences နဲ့ questions တွေမှာ သုံးပါ။"},{"concept":"Many – plural countable nouns","explanation":"We often use 'many' in negative sentences and questions, with plural countable nouns.","example":"I haven't got many chips. Have you got many eggs?","burmese":"'many' ကို plural countable nouns တွေနဲ့ negative sentences နဲ့ questions တွေမှာ သုံးပါ။"},{"concept":"A lot of – countable and uncountable nouns","explanation":"We often use 'a lot of' in affirmative and negative sentences and in questions, with countable and uncountable nouns.","example":"I have got a lot of apples. I haven't got a lot of tomatoes. Have you got a lot of water?","burmese":"'a lot of' ကို countable နဲ့ uncountable nouns တွေနဲ့ affirmative နဲ့ negative sentences တွေမှာ သုံးပါ။"},{"concept":"A lot (without 'of')","explanation":"We use 'of' when 'a lot' comes before a noun. But when there is no noun after 'a lot' we do not use 'of'.","example":"I've got a lot of bananas. Are there any bananas? Yes, there are a lot.","burmese":"'a lot' ရဲ့နောက်မှာ noun မရှိရင် 'of' ကို မသုံးပါ။"}]}$$::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00040000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 40), 'unit40-ex1', 'multiple_choice', 'Choose the correct quantity expression (much, many, a lot of, a lot) for each sentence.', $$[{"id":4001,"question":"There are ___ biscuits in the packet.","options":["a lot of","much","many"],"answer":"a lot of","explanation":"'a lot of' is used with countable nouns in affirmative sentences. 'biscuits' is plural countable. 'a lot of' ကို countable nouns နဲ့ affirmative sentences တွေမှာ သုံးပါ။","points":1},{"id":4002,"question":"There isn't ___ milk in the fridge.","options":["much","many","a lot of"],"answer":"much","explanation":"'much' is used with uncountable nouns in negative sentences. 'milk' is uncountable. 'much' ကို uncountable nouns နဲ့ negative sentences တွေမှာ သုံးပါ။","points":1},{"id":4003,"question":"Have you got ___ tomatoes?","options":["many","much","a lot"],"answer":"many","explanation":"'many' is used with plural countable nouns in questions. 'tomatoes' is plural countable. 'many' ကို plural countable nouns နဲ့ questions တွေမှာ သုံးပါ။","points":1},{"id":4004,"question":"There is ___ rice.","options":["a lot of","many","much"],"answer":"a lot of","explanation":"'a lot of' is used with uncountable nouns in affirmative sentences. 'rice' is uncountable. 'a lot of' ကို uncountable nouns နဲ့ affirmative sentences တွေမှာ သုံးပါ။","points":1},{"id":4005,"question":"Is there ___ water in the bottle?","options":["a lot of","many","much"],"answer":"a lot of","explanation":"'a lot of' is used with uncountable nouns in questions. 'water' is uncountable. 'a lot of' ကို uncountable nouns နဲ့ questions တွေမှာ သုံးပါ။","points":1},{"id":4006,"question":"How ___ times have you been to the USA?","options":["many","much","a lot of"],"answer":"many","explanation":"'many' is used with plural countable nouns. 'times' is plural countable. 'many' ကို plural countable nouns နဲ့ သုံးပါ။","points":1},{"id":4007,"question":"How ___ time do we have before the film starts?","options":["much","many","a lot of"],"answer":"much","explanation":"'much' is used with uncountable nouns. 'time' is uncountable. 'much' ကို uncountable nouns နဲ့ သုံးပါ။","points":1},{"id":4008,"question":"He spent ___ money on hair implants.","options":["a lot of","many","much"],"answer":"a lot of","explanation":"'a lot of' is used with uncountable nouns in affirmative sentences. 'money' is uncountable. 'a lot of' ကို uncountable nouns နဲ့ affirmative sentences တွေမှာ သုံးပါ။","points":1},{"id":4009,"question":"Today it rained ___.","options":["a lot","a lot of","much"],"answer":"a lot","explanation":"'a lot' (without 'of') is used when there is no noun after it. 'a lot' ကို 'a lot' ရဲ့နောက်မှာ noun မရှိတဲ့အခါ သုံးပါ။","points":1},{"id":4010,"question":"Haven't they sold ___ tickets?","options":["many","much","a lot of"],"answer":"many","explanation":"'many' is used with plural countable nouns in negative sentences and questions. 'tickets' is plural countable. 'many' ကို plural countable nouns နဲ့ negative sentences တွေမှာ သုံးပါ။","points":1},{"id":4011,"question":"How ___ people came?","options":["many","much","a lot of"],"answer":"many","explanation":"'many' is used with plural countable nouns. 'people' is plural countable. 'many' ကို plural countable nouns နဲ့ သုံးပါ။","points":1},{"id":4012,"question":"How ___ books are there? There are ___.","options":["many, a lot","much, a lot of","many, a lot of"],"answer":"many, a lot","explanation":"'many' is used with plural countable nouns like 'books'. 'a lot' (without 'of') is used when no noun follows. 'many' ကို plural countable nouns နဲ့ သုံးပါ။ noun မရှိရင် 'a lot' ကို သုံးပါ။","points":1},{"id":4013,"question":"Is there ___ milk in the fridge?","options":["much","many","a lot"],"answer":"much","explanation":"'much' is used with uncountable nouns in questions. 'milk' is uncountable. 'much' ကို uncountable nouns နဲ့ questions တွေမှာ သုံးပါ။","points":1},{"id":4014,"question":"I don't have ___ time.","options":["much","many","a lot of"],"answer":"much","explanation":"'much' is used with uncountable nouns in negative sentences. 'time' is uncountable. 'much' ကို uncountable nouns နဲ့ negative sentences တွေမှာ သုံးပါ။","points":1},{"id":4015,"question":"There are ___ cars on the street.","options":["a lot of","much","many"],"answer":"a lot of","explanation":"'a lot of' is used with countable nouns in affirmative sentences. 'cars' is plural countable. 'a lot of' ကို countable nouns နဲ့ affirmative sentences တွေမှာ သုံးပါ။","points":1},{"id":4016,"question":"Does it use ___ electricity?","options":["much","many","a lot of"],"answer":"much","explanation":"'much' is used with uncountable nouns in questions. 'electricity' is uncountable. 'much' ကို uncountable nouns နဲ့ questions တွေမှာ သုံးပါ။","points":1},{"id":4017,"question":"I like basketball ___.","options":["a lot","a lot of","much"],"answer":"a lot","explanation":"'a lot' (without 'of') is used when there is no noun after it. 'a lot' ကို 'a lot' ရဲ့နောက်မှာ noun မရှိတဲ့အခါ သုံးပါ။","points":1},{"id":4018,"question":"I haven't got ___ bread.","options":["much","many","a lot of"],"answer":"much","explanation":"'much' is used with uncountable nouns in negative sentences. 'bread' is uncountable. 'much' ကို uncountable nouns နဲ့ negative sentences တွေမှာ သုံးပါ။","points":1},{"id":4019,"question":"How ___ is the entrance fee?","options":["much","many","a lot of"],"answer":"much","explanation":"'much' is used to ask about price/quantity of uncountable things. 'entrance fee' is treated as uncountable here. 'much' ကို စျေးနှုန်းမေးဖို့ သုံးပါ။","points":1},{"id":4020,"question":"Does she want ___ dresses?","options":["many","much","a lot of"],"answer":"many","explanation":"'many' is used with plural countable nouns in questions. 'dresses' is plural countable. 'many' ကို plural countable nouns နဲ့ questions တွေမှာ သုံးပါ။","points":1},{"id":4021,"question":"I have ___ time.","options":["a lot of","many","much"],"answer":"a lot of","explanation":"'a lot of' is used with uncountable nouns in affirmative sentences. 'time' is uncountable. 'a lot of' ကို uncountable nouns နဲ့ affirmative sentences တွေမှာ သုံးပါ။","points":1},{"id":4022,"question":"I have ___ things to do.","options":["many","much","a lot of"],"answer":"many","explanation":"'many' is used with plural countable nouns in affirmative sentences. 'things' is plural countable. 'many' ကို plural countable nouns နဲ့ သုံးပါ။","points":1},{"id":4023,"question":"I dance ___.","options":["a lot","a lot of","much"],"answer":"a lot","explanation":"'a lot' (without 'of') is used when there is no noun after it. 'a lot' ကို 'a lot' ရဲ့နောက်မှာ noun မရှိတဲ့အခါ သုံးပါ။","points":1},{"id":4024,"question":"I don't have ___ friends.","options":["many","much","a lot of"],"answer":"many","explanation":"'many' is used with plural countable nouns in negative sentences. 'friends' is plural countable. 'many' ကို plural countable nouns နဲ့ negative sentences တွေမှာ သုံးပါ။","points":1},{"id":4025,"question":"He likes her very ___.","options":["much","many","a lot of"],"answer":"much","explanation":"'very much' is a fixed expression used after verbs to mean 'a great deal'. 'much' ကို 'very much' အဖြစ် verb ပြီးနောက်မှာ သုံးပါ။","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

